/** Pre-projected map data (generated by tools/gen-geo.mjs). Coordinates are SVG user units. */
export interface MapRegionData {
  id: string;
  name: string;
  /** SVG path. */
  d: string;
  /** [x0, y0, x1, y1] */
  bbox: [number, number, number, number];
  /** Label point (inside the shape) and the radius of the biggest circle that fits there. */
  lx: number;
  ly: number;
  lr: number;
}

export interface MapData {
  width: number;
  height: number;
  regions: MapRegionData[];
  /** Ocean zones (continents map only), drawn under the land. */
  oceans?: MapRegionData[];
  outline?: string;
  sphere?: string;
  graticule?: string;
}

export type MapKind = 'us' | 'continents' | 'countries';
export type PackId = 'us' | 'world' | 'countries';
export type PlayMode = 'find' | 'name' | 'learn';

/** A viewBox [x, y, w, h]. */
export type ViewBox = [number, number, number, number];

/** A magnified inset: `src` area of the map drawn again at `dst` (both in map units). */
export interface InsetSpec {
  src: ViewBox;
  dst: ViewBox;
}

export interface StageDef {
  id: string;
  pack: PackId;
  map: MapKind;
  title: string;
  emoji: string;
  /** Region ids asked in this stage. */
  targets: string[];
  /** Fixed camera for Find/Learn rounds of this stage (whole map when absent). */
  view?: ViewBox;
  inset?: InsetSpec;
  /** Tall screens (iPad portrait): a taller camera with the inset below the map instead of beside it. */
  portrait?: { view: ViewBox; inset: InsetSpec };
}

/** A region as the game sees it (land or ocean), with its kid-facing name and difficulty. */
export interface Region extends MapRegionData {
  /** Display/spoken name ("United States", "Pacific Ocean"). */
  label: string;
  /** Hint group shown after the first miss ("the West", "Europe"). */
  group?: string;
  prior: number;
  isOcean?: boolean;
}

export interface LoadedMap {
  kind: MapKind;
  data: MapData;
  /** Every tappable region (land + oceans) by id. */
  byId: Map<string, Region>;
  land: Region[];
  oceans: Region[];
}
